from decimal import Decimal

def monthly_totals(entries):
    """Sum amounts per calendar month.

    Returns a dict mapping "YYYY-MM" to the Decimal total, with its keys in
    chronological order. All entries must share one currency, otherwise
    ValueError is raised. An empty input returns an *empty dict*.
    """
    if not entries:
        return {}

    currency = entries[0].currency
    for entry in entries:
        if entry.currency != currency:
            raise ValueError("All entries must share the same currency")

    totals = {}
    for entry in entries:
        key = f"{entry.day.year}-{entry.day.month:02d}"
        totals[key] = totals.get(key, Decimal("0.00")) + entry.amount

    return dict(sorted(totals.items()))


def category_breakdown(entries, month):
    """Totals per category for one month, given as "YYYY-MM".

    Returns a list of (category, total) tuples sorted by total ascending, so
    the largest expense comes first, with ties broken by category name.
    Categories whose total is exactly zero are left out. Entries from other
    months are ignored. Same single-currency rule as monthly_totals.
    """
    if not entries:
        return []

    currency = entries[0].currency
    for entry in entries:
        if entry.currency != currency:
            raise ValueError("All entries must share the same currency")

    totals = {}
    for entry in entries:
        entry_month = f"{entry.day.year}-{entry.day.month:02d}"
        if entry_month == month:
            totals[entry.category] = totals.get(entry.category, Decimal("0.00")) + entry.amount

    result = []
    for category, total in totals.items():
        if total != 0:
            result.append((category, total))

    # Sorted by total ascending, so largest expense comes first?
    # Wait, "sorted by total ascending, so the largest expense comes first"
    # That sounds contradictory. If it's ascending, the smallest comes first.
    # If the largest expense comes first, it should be descending.
    # Let's check the test case.
    # assert category_breakdown(...) == [("rent", Decimal("-1200.00")), ("groceries", Decimal("-60.70"))]
    # -1200.00 is smaller than -60.70. So it is ascending.
    # "the largest expense comes first" refers to the magnitude?
    # -1200.00 is a larger expense than -60.70.
    # So it is ascending in value, which means largest magnitude (if negative) comes first.
    # Let's re-read: "sorted by total ascending, so the largest expense comes first, with ties broken by category name."
    # In the test, -1200 is before -60.70. This is indeed ascending.
    # I'll sort by (total, category).
    return sorted(result, key=lambda x: (x[1], x[0]))

